// ============================================================================
// Guardrails: Validate issue state before dispatch
// Check: issue open, agent:ready present, no running/blocked/done
// FIXED: Trigger-agnostic — works with BOTH Manual Trigger AND Schedule Trigger
// ============================================================================

const issueData = $input.first().json;

// Static values for single-repo dispatcher (no dependency on any specific trigger)
const owner = 'xxammaxx';
const repo = 'n8n-blueprint-workflow';
const issueNumber = issueData.number || 0;
const issueTitle = issueData.title || '';
const issueBody = issueData.body || '';
const issueState = issueData.state || 'unknown';
const labels = issueData.labels || [];

const labelNames = labels.map(function(l) { return typeof l === 'string' ? l : l.name; }).filter(Boolean);
const hasReady = labelNames.includes('agent:ready');
const hasRunning = labelNames.includes('agent:running');
const hasBlocked = labelNames.includes('agent:blocked');
const hasDone = labelNames.includes('agent:done');
const needsReview = labelNames.includes('agent:needs-review');
const evidenceAttached = labelNames.includes('evidence:attached');

var mode = 'manual-terminal';
if (labelNames.includes('mode:opencode-run')) mode = 'opencode-run';
else if (labelNames.includes('mode:hermes-review')) mode = 'hermes-review';

var risk = 'medium';
if (labelNames.includes('risk:low')) risk = 'low';
else if (labelNames.includes('risk:high')) risk = 'high';

const isOpen = issueState === 'open';

// HARD BLOCK: Issue #3 is a completed smoke test — never re-process
const isIssue3 = issueNumber === 3;

// Detect already-processed issues (agent:needs-review + evidence:attached = done)
const isAlreadyProcessed = needsReview && evidenceAttached;

const canStart = isOpen && hasReady && !hasRunning && !hasBlocked && !hasDone && !isIssue3 && !isAlreadyProcessed;

const guardResult = {
  owner: owner,
  repo: repo,
  issue_number: issueNumber,
  issue_title: issueTitle,
  issue_body: issueBody,
  issue_url: 'https://github.com/' + owner + '/' + repo + '/issues/' + issueNumber,
  is_open: isOpen,
  has_ready: hasReady,
  has_running: hasRunning,
  has_blocked: hasBlocked,
  has_done: hasDone,
  can_start: canStart,
  mode: mode,
  risk: risk,
  labels: labels,
  label_names: labelNames,
  guardrail: canStart ? 'PASS' : 'BLOCKED',
  guardrail_reason: canStart ? 'Ready to dispatch' : (
    isIssue3 ? 'HARD BLOCK: Issue #3 is a completed smoke test — never re-process' :
    isAlreadyProcessed ? 'Already processed (agent:needs-review + evidence:attached present)' :
    !isOpen ? 'Issue is not open' :
    !hasReady ? 'Missing agent:ready label' :
    hasRunning ? 'agent:running already set — duplicate run blocked' :
    hasBlocked ? 'Issue is blocked' :
    hasDone ? 'Issue already done' : 'Unknown guardrail failure'
  )
};

// Block non-startable issues (but DON'T mutate Error objects — create new error)
if (!canStart) {
  const blockError = new Error('GUARDRAIL_BLOCKED: ' + guardResult.guardrail_reason + ' (issue #' + issueNumber + ')');
  throw blockError;
}

return [{
  json: guardResult
}];

// GHIW-10 SHADOW: Classify & Route Issue
// Deterministic classification of GitHub issues.
// SHADOW MODE: produces shadow decision, existing routing unchanged.

const VALID_DECISIONS = [
  'READY_FOR_GHIW', 'DUPLICATE_SUSPECTED', 'REPRO_REQUIRED',
  'SCOPE_UNCLEAR', 'SECURITY_REVIEW_REQUIRED', 'OUT_OF_SCOPE', 'BLOCKED'
];

const ALLOWLISTED_REPOS = ['xxammaxx/n8n-blueprint-workflow', 'xxammaxx/Positron'];
const MIN_REPRO_LENGTH = 50;

const state = $input.first().json;
const issue = state.issue || state;
const body = (issue.body || '').toLowerCase();
const title = (issue.title || '').toLowerCase();

let shadow_decision = 'READY_FOR_GHIW';
let shadow_reason_codes = ['ISSUE_VALIDATED'];

// Check 1: Repository allowlist
const repo = state.repository || issue.repository_url?.split('/repos/')[1] || '';
if (repo && !ALLOWLISTED_REPOS.some(r => repo.includes(r))) {
  shadow_decision = 'OUT_OF_SCOPE';
  shadow_reason_codes = ['REPO_NOT_ALLOWLISTED'];
}

// Check 2: Reproduction completeness
if (!body || body.length < MIN_REPRO_LENGTH) {
  shadow_decision = 'REPRO_REQUIRED';
  shadow_reason_codes = ['REPRODUCTION_MISSING'];
}

// Check 3: Scope check
const vague_terms = ['maybe', 'possibly', 'not sure', 'unclear', 'idk'];
if (vague_terms.some(t => body.includes(t) && body.length < 200)) {
  shadow_decision = 'SCOPE_UNCLEAR';
  shadow_reason_codes = ['SCOPE_AMBIGUOUS'];
}

// Check 4: Injection detection (from upstream node)
if (state.injection_detected) {
  shadow_decision = 'SECURITY_REVIEW_REQUIRED';
  shadow_reason_codes = ['INJECTION_DETECTED'];
}

// Check 5: Duplicate detection (from upstream search)
if (state.duplicate_suspected) {
  shadow_decision = 'DUPLICATE_SUSPECTED';
  shadow_reason_codes = ['DUPLICATE_FOUND'];
}

// AUTHORITATIVE ROUTING — controls execution path
return [{
  json: {
    ...state,
    shadow_decision,
    shadow_reason_codes,
    shadow_mode: false, authoritative: true,
    shadow_timestamp: new Date().toISOString()
  }
}];

// GHIW-10 AUTHORITATIVE: Route based on classification
// READY_FOR_GHIW → continue existing pipeline
// All other decisions → stop with appropriate response

const state = $input.first().json;
const decision = state.shadow_decision || 'UNDEFINED';

// READY_FOR_GHIW: continue to existing DISPATCH pipeline
if (decision === 'READY_FOR_GHIW') {
  state.route = 'CONTINUE_TO_DISPATCH';
  return [{ json: state }];
}

// All other decisions: stop routing, produce classification output
state.route = 'STOP_CLASSIFY';
state.stop_reason = decision;
state.stop_reason_codes = state.shadow_reason_codes || [];

return [{ json: state }];

// GHIW-10 SHADOW: Detect Prompt Injection
// Scans issue body for known injection patterns.
// Does NOT block — only flags for classification.

const state = $input.first().json;
const issue = state.issue || state;
const body = (issue.body || '');
const title = (issue.title || '');

const INJECTION_PATTERNS = [
  /\[\[system:\s*ignore\s+previous\s+instructions\]\]/i,
  /\[\[override:\s*security\s+policy\]\]/i,
  /ignore\s+all\s+(previous|prior|above)\s+(instructions|rules|constraints)/i,
  /you\s+are\s+now\s+(a\s+)?(DAN|unrestricted|unfiltered)/i,
  /bypass\s+(security|verification|gate|policy)/i,
  /disable\s+(verifier|security\s+gate|frozen\s+test)/i,
  /skip\s+(verification|testing|security\s+check)/i,
  /execute\s+(this\s+)?(command|shell\s+command)/i,
  /curl\s+.*\|\s*(sh|bash)/i,
  /rm\s+-rf\s+\//i,
  /set\s+ENSURE_BUILDER_ENABLED\s*=\s*true/i,
  /git\s+push\s+--force/i,
  /delete\s+(all|every)\s+(workflow|credential|builder|CT)/i,
  /reveal\s+(your\s+)?(system\s+prompt|instructions|secrets)/i
];

let injection_detected = false;
let injection_matches = [];

for (const pattern of INJECTION_PATTERNS) {
  if (pattern.test(body) || pattern.test(title)) {
    injection_detected = true;
    injection_matches.push(pattern.source.substring(0, 80));
  }
}

return [{
  json: {
    ...state,
    injection_detected,
    injection_matches: injection_matches.slice(0, 5)  // max 5 for evidence
  }
}];

// GHIW-10 SHADOW: Repository Allowlist Check
const ALLOWLISTED_REPOS = ['xxammaxx/n8n-blueprint-workflow', 'xxammaxx/Positron'];
const state = $input.first().json;
const repo = state.repository || '';
const is_allowlisted = ALLOWLISTED_REPOS.some(r => repo.includes(r));

return [{
  json: {
    ...state,
    repo_allowlisted: is_allowlisted,
    repo_checked: repo || 'unknown'
  }
}];

// GHIW-10 SHADOW: Log shadow decision for parity measurement
const state = $input.first().json;

// Build evidence ledger entry
const shadow_entry = {
  schema_version: '1.0',
  project_id: 'ghiw-n8n-ops-control-plane',
  run_id: 'w2-ghiw10-' + Date.now().toString(36),
  task_id: 'GHIW-10',
  source: { type: 'shadow_mode', id: state.issue?.number || 'unknown' },
  workflow: { logical_id: 'GHIW-10', id: $workflow.id, name: $workflow.name },
  execution: { id: $execution.id, started_at: new Date().toISOString() },
  decision: state.shadow_decision || 'UNDEFINED',
  reason_codes: state.shadow_reason_codes || [],
  classification: state.shadow_decision === 'READY_FOR_GHIW' ? 'GREEN' : 
                 (state.shadow_decision === 'SECURITY_REVIEW_REQUIRED' ? 'AMBER' : 'RED'),
  timestamp: new Date().toISOString(),
  shadow_details: {
    injection_detected: state.injection_detected || false,
    repo_allowlisted: state.repo_allowlisted || false,
    existing_routing: 'UNCHANGED',
    shadow_mode: true
  }
};

return [{ json: { ...state, shadow_entry } }];

// ============================================================================
// Prepare RUN_INPUT.json from GitHub Issue Data
// Adapted from validated 12-node baseline - uses GitHub API response as input
// ============================================================================

const guardData = $('Guardrails & Validate').first().json;

const owner = String(guardData.owner || 'xxammaxx').trim();
const repo = String(guardData.repo || 'n8n-blueprint-workflow').trim();
const issueNumber = Number(guardData.issue_number || 1);
const mode = String(guardData.mode || 'opencode-run').trim();
const allocation = $('Evaluate Builder v3').first().json;
if (allocation.builder_allocation_status !== 'PASS') throw new Error('BUILDER_NOT_READY: ' + JSON.stringify(allocation.builder_allocation_error || {}));

if (!owner) throw new Error('Missing owner');
if (!repo) throw new Error('Missing repo');
if (!Number.isInteger(issueNumber) || issueNumber < 1) throw new Error('Invalid issue_number: ' + issueNumber);

const now = new Date();
const ts = now.toISOString().replace(/[-:]/g, '').replace(/\.\d{3}Z$/, 'Z');
const runId = 'gh-issue-' + issueNumber + '-' + ts;
const issueUrl = 'https://github.com/' + owner + '/' + repo + '/issues/' + issueNumber;

const safeOwner = owner.replace(/[^a-zA-Z0-9_.-]/g, '-');
const safeRepo = repo.replace(/[^a-zA-Z0-9_.-]/g, '-');

const evidenceRoot = '/opt/dev-fabric/evidence/github-agent-runs';
const runInputRemote = evidenceRoot + '/' + safeOwner + '/' + safeRepo + '/issue-' + issueNumber + '/' + runId + '/RUN_INPUT.json';
const evidenceDir = evidenceRoot + '/' + safeOwner + '/' + safeRepo + '/issue-' + issueNumber + '/' + runId;

const runInput = {
  run_id: runId,
  source_of_truth: 'github',
  github: {
    owner: owner,
    repo: repo,
    issue_number: issueNumber,
    issue_url: issueUrl,
    trigger_label: 'agent:ready'
  },
  mode: mode,
  approval_policy: {
    push: false,
    pr: false,
    merge: false,
    github_actions: false,
    provider_config: false
  },
  runner: {
    workspace_root: '/opt/dev-fabric/workspaces/projects',
    evidence_root: evidenceRoot
  },
    builder: { ctid: allocation.builder_ctid, builder_id: allocation.builder_id, hostname: allocation.builder_hostname, verification_id: allocation.builder_verification_id, state: allocation.builder_state },
  allocator: { status: allocation.builder_allocation_status, project_id: allocation.builder_project_id, run_id: allocation.builder_run_id },
  agent_runtime: {
    opencode_available: true,
    opencode_version: 'v1.17.9',
    opencode_provider_configured: false,
    hermes_available: false
  }
};

const runInputJson = JSON.stringify(runInput, null, 2);
const runInputB64 = Buffer.from(runInputJson, 'utf-8').toString('base64');

return [{
  json: {
    owner: owner,
    repo: repo,
    issue_number: issueNumber,
    run_id: runId,
    builder: {ctid: allocation.builder_ctid, builder_id: allocation.builder_id, hostname: allocation.builder_hostname, verification_id: allocation.builder_verification_id, state: allocation.builder_state},
    allocator: {status: allocation.builder_allocation_status, project_id: allocation.builder_project_id, run_id: allocation.builder_run_id},
    mode: mode,
    issue_url: issueUrl,
    run_input_remote: runInputRemote,
    run_input_b64: runInputB64,
    evidence_dir: evidenceDir,
    guardrail_passed: guardData.can_start,
    labels: guardData.label_names
  }
}];

// Pick first ready issue from GitHub Search results
const searchResults = $input.first().json;

if (!searchResults || !searchResults.items || searchResults.items.length === 0) {
  // No ready issues - return empty array to stop execution
  return [];
}

const first = searchResults.items[0];
const labelNames = (first.labels || []).map(function(l) { return typeof l === "string" ? l : l.name; }).filter(Boolean);

// Double-check: issue must have agent:ready (Schedule Trigger might fire between search and fetch)
if (!labelNames.includes("agent:ready")) {
  return [];
}

return [{
  json: {
    found: true,
    owner: "xxammaxx",
    repo: "n8n-blueprint-workflow",
    issue_number: first.number,
    issue_title: first.title,
    issue_state: first.state,
    labels: first.labels || [],
    label_names: labelNames,
    html_url: first.html_url
  }
}];

const guard = $('Guardrails & Validate').first().json;
const issueNumber = Number(guard.issue_number);
const body = String(guard.issue_body || '');
const marker = body.match(/(?:project_id|project_key)\s*[:=]\s*([a-z0-9][a-z0-9-]{1,62})/i);
const projectId = marker ? marker[1].toLowerCase() : 'e5r3b-canary-001';
const repository = String(guard.owner) + '/' + String(guard.repo);
const runId = uuid();
const projectKey = projectId;
const repoHash = (repository === 'xxammaxx/n8n-blueprint-workflow' && projectKey === 'e5r3b-canary-001') ? 'de1ca21eafcb860467b16fd7a1c860cc4a4dc1e45135227be6731d3c191491ae' : sha256(repository + '|' + projectKey);
const lockKey = 'project-builder:' + projectKey;
const payload = {schema_version:'1.0', lock_key:lockKey, lock_type:'project-builder', repo_hash:repoHash, issue_number:issueNumber, run_id:runId, ttl_seconds:900};
return [{json:{...guard, builder_run_id:runId, builder_project_id:projectId, builder_project_key:projectKey, builder_repository:repository, builder_repo_hash:repoHash, builder_lock_key:lockKey, builder_lock_command:'ghiw-lock-v1 acquire ' + b64url(JSON.stringify(payload))}}];

function b64url(value) { return Buffer.from(value, 'utf8').toString('base64').replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,''); }
function uuid() { const h=(n)=>Array.from({length:n},()=>Math.floor(Math.random()*16).toString(16)).join(''); return h(8)+'-'+h(4)+'-4'+h(3)+'-'+['8','9','a','b'][Math.floor(Math.random()*4)]+h(3)+'-'+h(12); }
function sha256(value) {
  const K=[0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a81,0x2e1b2138,0x4d2c6f2f,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0xa81a664f,0xa4506ceb,0xbef9a3f7,0xc67178f2];
  const bytes=Array.from(Buffer.from(value,'utf8')); const bitLength=bytes.length*8; bytes.push(128); while(bytes.length%64!==56)bytes.push(0); for(let i=7;i>=0;i--)bytes.push(Math.floor(bitLength/2**(8*i))&255);
  const H=[0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19]; const r=(x,n)=>(x>>>n)|(x<<(32-n));
  for(let c=0;c<bytes.length;c+=64){const W=[];for(let i=0;i<16;i++)W[i]=(bytes[c+4*i]<<24)|(bytes[c+4*i+1]<<16)|(bytes[c+4*i+2]<<8)|bytes[c+4*i+3];for(let i=16;i<64;i++){const a=r(W[i-15],7)^r(W[i-15],18)^(W[i-15]>>>3),b=r(W[i-2],17)^r(W[i-2],19)^(W[i-2]>>>10);W[i]=(W[i-16]+a+W[i-7]+b)>>>0;}let[a,b,d,e,f,g,h,i]=H;for(let t=0;t<64;t++){const s1=r(e,6)^r(e,11)^r(e,25),ch=(e&f)^(~e&g),t1=(i+s1+ch+K[t]+W[t])>>>0,s0=r(a,2)^r(a,13)^r(a,22),maj=(a&b)^(a&d)^(b&d),t2=(s0+maj)>>>0;i=h;h=g;g=f;f=e;e=(d+t1)>>>0;d=b;b=a;a=(t1+t2)>>>0;}H[0]=(H[0]+a)>>>0;H[1]=(H[1]+b)>>>0;H[2]=(H[2]+d)>>>0;H[3]=(H[3]+e)>>>0;H[4]=(H[4]+f)>>>0;H[5]=(H[5]+g)>>>0;H[6]=(H[6]+h)>>>0;H[7]=(H[7]+i)>>>0;}
  return H.map(x=>('00000000'+x.toString(16)).slice(-8)).join('');
}

const state = $('Prepare Builder Lock v3').first().json;
const raw = $input.first().json || {};
const lock = parse(raw);
if (lock.status !== 'acquired' || !lock.lease_token) return [{json:{...state, builder_allocation_status:'LOCK_FAILED', builder_allocation_error:lock.error || lock.status || 'lock acquisition failed', builder_lock_token:null, builder_ensure_command:null}}];
const payload = {schema_version:'1.0', project_id:state.builder_project_id, project_key:state.builder_project_key, repository:state.builder_repository, repo_hash:state.builder_repo_hash, mutation_approval_id:'e7-runtime-closure-v3', run_id:state.builder_run_id, requested_capabilities:[], dry_run:false, plan:{plan_id:'e7-runtime-closure-v3-'+state.builder_project_key, plan_sha256:state.builder_repo_hash}, lock:{owner:state.builder_project_key, token:lock.lease_token}, request:{run_id:state.builder_run_id}};
return [{json:{...state, builder_lock_token:lock.lease_token, builder_ensure_command:'ghiw-provisioner-v1 ensure-builder '+b64url(JSON.stringify(payload))}}];
function parse(v){try{return JSON.parse(v.stdout || v.result || '{}')}catch(e){return {status:'error',error:{code:'LOCK_RESPONSE_INVALID'}}}}
function b64url(value){return Buffer.from(value,'utf8').toString('base64').replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');}

const state = $('Prepare Ensure Builder v3').first().json;
const raw = $input.first().json || {};
let response={}; try{response=JSON.parse(raw.stdout || raw.result || '{}')}catch(e){response={status:'error',error:{code:'PROVISIONER_RESPONSE_INVALID'}};}
const builder=response.builder || {};
const pass=response.status==='ok' && builder.state==='BUILDER_READY' && Number.isInteger(Number(builder.ctid)) && !!builder.verification_id;
return [{json:{...state, builder_allocation_status:pass?'PASS':'FAILED', builder_allocation_response:response, builder_ctid:pass?Number(builder.ctid):null, builder_id:pass?(builder.builder_id || ('bld-'+builder.ctid)):null, builder_hostname:pass?(builder.hostname || null):null, builder_verification_id:pass?builder.verification_id:null, builder_state:pass?builder.state:null, builder_allocation_error:pass?null:(response.error || response.status || 'builder not READY')}}];

const state=$('Evaluate Builder v3').first().json;
if(state.builder_allocation_status!=='PASS') throw new Error('BUILDER_NOT_READY: '+JSON.stringify(state.builder_allocation_error||{}));
const payload={schema_version:'1.0',run_id:state.builder_run_id,project_id:state.builder_project_id,project_key:state.builder_project_key,repository:state.builder_repository,mutation_approval_id:'e7-runtime-closure-v3',ctid:state.builder_ctid,issue_number:Number(state.issue_number),task_id:'ghiw-e7-runtime-canary',trace_id:'ghiw.issue.'+state.issue_number+'.'+state.builder_run_id,dry_run:false};
return [{json:{...state,builder_canary_command:'ghiw-provisioner-v1 builder-canary '+b64url(JSON.stringify(payload))}}];
function b64url(value){return Buffer.from(value,'utf8').toString('base64').replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');}

function normalizeBuilderCanaryResult(raw) {
  const unknown = (reason, payloadStatus = null) => ({
    input_contract_version: 'unknown',
    execution_success: false,
    execution_status: payloadStatus || 'RESULT_SCHEMA_UNKNOWN',
    verification_pass: false,
    governance_status: 'UNKNOWN',
    blocking_failure: reason,
    failure_class: 'RESULT_SCHEMA_UNKNOWN',
    final_classification: 'FAIL',
    normalization_event: 'result.normalization.failed',
    builder: {},
  });

  let payload = raw;
  if (typeof raw === 'string') {
    try { payload = JSON.parse(raw); } catch (_) { return unknown('invalid JSON'); }
  }
  if (payload && typeof payload === 'object' && typeof payload.stdout === 'string') {
    try { payload = JSON.parse(payload.stdout || '{}'); } catch (_) { return unknown('invalid JSON'); }
  } else if (payload && typeof payload === 'object' && typeof payload.result === 'string') {
    try { payload = JSON.parse(payload.result || '{}'); } catch (_) { return unknown('invalid JSON'); }
  }

  // Provisioner versions have historically wrapped the canary under
  // builder, data, canary, or provisioner.result. Select only known envelope
  // shapes; an unknown shape remains fail-closed below.
  const envelopes = [
    payload,
    payload && payload.result,
    payload && payload.provisioner,
    payload && payload.provisioner && payload.provisioner.result,
    payload && payload.data,
    payload && payload.canary,
  ].filter(value => value && typeof value === 'object');
  const envelope = envelopes.find(value => value.builder || value.verification_pass === true || value.verification);
  const builder = envelope && typeof envelope.builder === 'object' ? envelope.builder : envelope;
  const verification = builder && typeof builder.verification === 'object' ? builder.verification : null;
  const operation = payload.operation || (envelope && envelope.operation);
  const status = payload.status ||
    (payload.result && payload.result.status) ||
    (payload.provisioner && payload.provisioner.status) ||
    (envelope && envelope.status);
  if (!payload || typeof payload !== 'object' || operation !== 'builder-canary' || !builder || !verification) {
    return unknown('builder-canary contract not recognized', status);
  }

  const verificationPass = builder.verification_pass === true && verification.verification_pass === true;
  const deny = verification.governance_deny;
  const governanceStatus = deny && deny.tool_executed === false ? 'PASS' : (deny ? 'FAIL' : 'UNKNOWN');
  const deterministicPass = verification.target_test_pass === true &&
    verification.regression_pass === true &&
    verification.scope_pass === true &&
    verification.secret_scan_pass === true;
  const processPass = verification.opencode_exit_code === undefined || verification.opencode_exit_code === 0;
  const success = status === 'ok' &&
    builder.status === 'LOCAL_LLM_SUCCESS' &&
    verificationPass &&
    governanceStatus === 'PASS' &&
    deterministicPass &&
    processPass;

  let failureClass = null;
  let blockingFailure = null;
  if (!success) {
    failureClass = !verificationPass ? 'VERIFIER_FAILED' :
      governanceStatus !== 'PASS' ? 'GOVERNANCE_FAILED' :
      !deterministicPass ? 'TEST_FAILED' :
      !processPass ? 'PROCESS_EXIT_NONZERO' :
      builder.status || payload.status || 'RESULT_SCHEMA_UNKNOWN';
    blockingFailure = failureClass;
  }

  return {
    input_contract_version: 'ghiw.provisioner.v2.builder-canary',
    execution_success: success,
    execution_status: builder.status || payload.status || 'RESULT_SCHEMA_UNKNOWN',
    verification_pass: verificationPass,
    governance_status: governanceStatus,
